# Rallonges des articles du lexique tech et du jargon.
from wiki_content import RN
P = lambda *xs: ''.join(f'<p>{x}</p>' for x in xs)
UL = lambda *xs: '<ul>' + ''.join(f'<li>{x}</li>' for x in xs) + '</ul>'
SN = lambda c: f'<pre class="snip"><code>{c}</code></pre>'

EXT2 = {
'html': [('Exemple', SN('&lt;h1&gt;Salut, moi c’est Wyatt.&lt;/h1&gt;\n&lt;p&gt;Je code. Beaucoup.&lt;/p&gt;\n&lt;a href="/perso/wiki/"&gt;Wyattpédia&lt;/a&gt;') + P('Trois lignes, et on a un titre, un paragraphe et un lien.')),
         ('Le HTML qui compte pour le SEO', P('Google lit le HTML pour comprendre une page. Un seul grand titre <code>h1</code>, des sous-titres <code>h2</code> bien rangés, des images avec un texte alternatif : ça aide les moteurs de recherche et les personnes qui utilisent un lecteur d’écran.'))],
'css': [('Exemple', SN('.bouton {\n  background: black;\n  color: white;\n  border-radius: 12px;\n  transition: transform .3s;\n}\n.bouton:hover { transform: translateY(-2px); }') + P('Un bouton noir, aux coins arrondis, qui monte un peu quand on le survole.')),
        ('Les animations en CSS', P('Le CSS sait animer tout seul : <code>transition</code> pour un changement en douceur, <code>@keyframes</code> pour une animation complète. Beaucoup d’effets de cette page sont du pur CSS, sans une ligne de JavaScript.'))],
'php': [('Exemple', SN('&lt;?php\n$nom = "Wyatt";\necho "Salut, $nom !";\n?&gt;') + P('Le serveur exécute ce code et envoie au navigateur : « Salut, Wyatt ! ».')),
        ('Toujours vivant', P('On annonce souvent la fin de PHP, et il est toujours là. Il a beaucoup évolué, et des outils comme Laravel le rendent moderne et agréable. Pour un hébergement simple et pas cher, il reste un choix très courant.'))],
'sql': [('Les quatre gestes de base', UL('<code>SELECT</code> : lire.', '<code>INSERT</code> : ajouter.', '<code>UPDATE</code> : modifier.', '<code>DELETE</code> : supprimer. À manier avec précaution.') + P('Un <code>DELETE</code> sans condition supprime tout le tableau. Les développeurs ont tous une histoire de ce genre ' + RN + '.')),
        ('Où on le trouve', P('Dans presque toutes les applications qui gèrent des comptes, des commandes ou des messages. Les bases les plus connues sont MySQL, PostgreSQL et SQLite.'))],
'api': [('À quoi ressemble une réponse', SN('{\n  "pseudo": "Wyatt",\n  "role": "dieu du code",\n  "sommeil": null\n}') + P('Une API répond souvent en JSON : un format simple, que n’importe quel programme sait lire.')),
        ('Les règles du jeu', P('La plupart des API demandent une clé ou un jeton pour savoir qui les appelle, et limitent le nombre de demandes par minute. Une clé d’API, c’est comme un mot de passe : elle ne doit jamais être publiée.'))],
'json': [('Les règles', UL('Les textes sont entre guillemets doubles.', 'Les objets sont entre accolades, les listes entre crochets.', 'Pas de virgule après le dernier élément.', 'Pas de commentaires.') + P('Une seule virgule en trop, et tout le fichier est refusé. Un cauchemar pour les maniaques de la ponctuation. Donc un plaisir pour Wyatt.')),
         ('Pourquoi il a gagné', P('Avant JSON, on échangeait souvent des données en XML, plus lourd et plus bavard. JSON est plus court, plus lisible, et ressemble directement aux objets de JavaScript. Il est devenu la langue commune des API.'))],
'git': [('Les commandes de base', SN('git status        # qu’est-ce qui a changé ?\ngit add .         # préparer les changements\ngit commit -m "…" # enregistrer\ngit push          # envoyer sur GitHub')),
        ('Les branches', P('Une branche, c’est une copie parallèle du projet pour essayer quelque chose sans casser la version principale. Si l’essai marche, on la fusionne. Sinon, on l’oublie. Et parfois, la fusion se passe mal : voir conflit de fusion.'))],
'github-pages': [('Brancher son nom de domaine', UL('Ajouter un fichier <code>CNAME</code> avec le nom du site.', 'Faire pointer les DNS du domaine vers GitHub.', 'Activer HTTPS dans les réglages.') + P('C’est exactement ce qui a été fait pour www.siroxtag.fr, avec un domaine acheté chez OVH.')),
                 ('Les limites à connaître', P('Le service est gratuit mais public : le code du site est visible sur GitHub. Il ne faut donc jamais y mettre de mot de passe ou de clé secrète. Pour un site vitrine, ce n’est pas un problème.'))],
'dns': [('Les enregistrements courants', UL('<b>A</b> : un nom vers une adresse IPv4.', '<b>AAAA</b> : un nom vers une adresse IPv6.', '<b>CNAME</b> : un nom vers un autre nom.', '<b>MX</b> : où livrer les e-mails.', '<b>TXT</b> : des informations de vérification.')),
        ('Le temps de propagation', P('Chaque enregistrement a une durée de vie, le TTL. Tant qu’elle n’est pas écoulée, certains ordinateurs gardent l’ancienne réponse en mémoire. D’où ces moments où le site marche chez l’un et pas chez l’autre.'))],
'https': [('Comment vérifier', P('Le cadenas à gauche de l’adresse indique une connexion chiffrée. En cliquant dessus, on voit qui a délivré le certificat. Attention : le cadenas prouve que la connexion est sécurisée, pas que le site est honnête. Un site d’arnaque peut avoir un cadenas.')),
          ('Pourquoi c’est obligatoire aujourd’hui', P('Les navigateurs affichent « Non sécurisé » sur les sites sans HTTPS, et Google les met en retrait. Avec des certificats gratuits, il n’y a plus aucune excuse.'))],
'cache': [('Les différents caches', UL('Le cache du navigateur, sur ton appareil.', 'Le cache du CDN, réparti dans le monde.', 'Le cache du serveur, pour éviter de recalculer.', 'Le cache DNS, pour les adresses.') + P('Quatre endroits où une vieille version peut se cacher. Bonne chasse.')),
          ('La blague', P('« Il n’y a que deux choses difficiles en informatique : invalider le cache et nommer les choses. » Cette phrase est célèbre chez les développeurs. Wyatt confirme pour la première.'))],
'hydratation': [('Pourquoi on fait ça', P('Envoyer une page déjà prête, c’est rapide : le visiteur voit le contenu tout de suite, et Google aussi. Mais pour que les boutons marchent, il faut le JavaScript. L’hydratation réunit les deux : la vitesse du serveur et l’interactivité du navigateur.')),
                ('Les causes d’erreur classiques', UL('Une date ou une heure affichée différemment côté serveur et côté navigateur.', 'Un nombre aléatoire tiré deux fois.', 'Du contenu qui dépend de la taille de l’écran.', 'Une extension du navigateur qui modifie la page.'))],
'seo': [('Les trois piliers', UL('<b>La technique</b> : un site rapide, bien structuré, sans erreurs.', '<b>Le contenu</b> : des pages qui répondent vraiment aux questions des gens.', '<b>La popularité</b> : des liens venant d’autres sites de confiance.')),
        ('Les balises qui comptent', P('Le <code>title</code>, qui s’affiche dans les résultats de Google, et la meta description, le petit texte en dessous. Bien rédigés, ils donnent envie de cliquer. Ce sont les deux premières choses à soigner sur une page.'))],
'front-end': [('Les outils du front', UL('HTML, CSS, JavaScript : la base.', 'Des frameworks comme React.', 'Les outils de développement du navigateur (touche F12).', 'Beaucoup de patience avec les différents navigateurs.')),
              ('L’accessibilité', P('Un bon front-end marche pour tout le monde : au clavier, avec un lecteur d’écran, avec des animations réduites. Ce site respecte, par exemple, le réglage « réduire les animations » de ton appareil.'))],
'back-end': [('Les outils du back', UL('Des langages : PHP, JavaScript avec Node.js, Python…', 'Des bases de données : SQL et autres.', 'Des API pour parler aux autres services.', 'Des serveurs, ou des fonctions serverless.')),
             ('La sécurité avant tout', P('C’est souvent dans le back-end que se cachent les failles les plus graves : mots de passe mal rangés, droits d’accès mal vérifiés, injections SQL. Un bon développeur back pense comme un attaquant pour mieux se défendre.'))],
'framework': [('Bibliothèque ou framework ?', P('Une bibliothèque, on l’appelle quand on en a besoin. Un framework, c’est lui qui appelle ton code, selon ses règles. La nuance fait débattre les développeurs pendant des heures.')),
              ('Les plus connus', UL('Front-end : React, Vue, Svelte.', 'Back-end : Laravel (PHP), Express (Node.js), Django (Python).', 'Les deux : Next.js.'))],
'react': [('Exemple', SN('function Salut({ nom }) {\n  return &lt;h1&gt;Salut, {nom} !&lt;/h1&gt;;\n}') + P('Un composant React : une fonction qui renvoie un morceau de page. On peut l’utiliser partout.')),
          ('Pourquoi Wyatt ne l’utilise pas ici', P('Pour un site vitrine léger, React serait trop lourd. Mais pour un vrai SaaS, avec des dizaines d’écrans et de données qui changent tout le temps, il devient très pratique. C’est une question d’outil adapté au projet.'))],
'nodejs': [('Exemple', SN('// serveur.js\nrequire("http").createServer((req, res) =&gt; {\n  res.end("Salut !");\n}).listen(3000);') + P('Quatre lignes, et on a un serveur web qui répond « Salut ! ».')),
           ('Un seul fil, beaucoup de choses', P('Node.js traite les tâches les unes après les autres, mais sans attendre bêtement : pendant qu’une requête attend une réponse, il en traite d’autres. C’est très efficace pour les bots et les API.'))],
'npm': [('Les commandes utiles', SN('npm install      # installer les dépendances\nnpm start        # lancer le projet\nnpm run deploy   # lancer un script perso')),
        ('Attention aux paquets', P('N’importe qui peut publier un paquet sur npm. Avant d’en installer un, on vérifie qu’il est connu, maintenu et utilisé par d’autres. Des paquets malveillants existent, qui essaient de voler des clés secrètes.'))],
'discord-js': [('Exemple', SN('client.on("interactionCreate", async i =&gt; {\n  if (i.commandName === "ping") {\n    await i.reply({ content: "Pong !", ephemeral: true });\n  }\n});') + P('Le bot répond « Pong ! » à la commande <code>/ping</code>, en privé.')),
               ('Les intents', P('Discord demande aux bots de déclarer ce qu’ils veulent écouter : les messages, les membres, les réactions… On les appelle les « intents ». Le bot des impôts n’a besoin d’aucun intent sensible, grâce aux commandes slash.'))],
'commandes-slash': [('Les avantages', UL('Le membre voit les commandes disponibles en tapant <code>/</code>.', 'Les options sont proposées et vérifiées par Discord.', 'Les réponses peuvent être privées.', 'Pas besoin de lire tous les messages du serveur.')),
                    ('Le déploiement', P('Les commandes doivent être déclarées auprès de Discord avant d’apparaître. Pour le bot des impôts, c’est la commande <code>npm run deploy</code>, à relancer à chaque changement.'))],
'luau': [('Exemple', SN('local lampe = workspace.Lampe\nlampe.Touched:Connect(function()\n  lampe.PointLight.Enabled = true\nend)') + P('Quand un joueur touche la lampe, elle s’allume. La créature de BLACKOUT n’apprécie pas.')),
         ('Pourquoi c’est un bon début', P('Créer un jeu sur Roblox, c’est voir tout de suite le résultat de son code, en 3D, avec ses amis. Beaucoup de développeurs ont commencé comme ça.'))],
'typescript': [('Les avantages', UL('L’éditeur repère les erreurs pendant qu’on tape.', 'L’autocomplétion devient beaucoup plus précise.', 'Le code est plus facile à relire, des mois plus tard.')),
               ('Les inconvénients', P('Il faut une étape de compilation, et écrire les types prend un peu de temps au début. Pour un petit script, c’est parfois trop. Pour un gros projet, beaucoup ne pourraient plus s’en passer.'))],
'serveur': [('Physique ou virtuel', P('Un serveur peut être une vraie machine dans un centre de données, ou un serveur « virtuel », une part d’une grosse machine partagée. La plupart des sites tournent aujourd’hui sur des serveurs virtuels, dans le cloud.')),
            ('Le centre de données', P('Des milliers de serveurs alignés dans des armoires, refroidis en permanence, avec des générateurs de secours. Quand on dit « le cloud », c’est en réalité ces bâtiments bien réels.'))],
'hebergement': [('Les grandes familles', UL('<b>Statique</b> : des fichiers servis tels quels. Simple, rapide, souvent gratuit.', '<b>Mutualisé</b> : un serveur partagé avec d’autres sites, pas cher.', '<b>VPS</b> : un serveur virtuel à soi, plus de liberté.', '<b>Serverless</b> : des fonctions lancées à la demande.')),
                ('Bien choisir', P('On choisit selon le projet : un portfolio n’a pas besoin du même hébergement qu’un SaaS avec des milliers d’utilisateurs. Commencer simple, et évoluer quand c’est nécessaire.'))],
'serverless': [('Exemple', SN('// api/salut.js\nexport default function handler(req, res) {\n  res.json({ message: "Salut !" });\n}') + P('Sur Vercel, ce fichier devient automatiquement une adresse qui répond en JSON.')),
               ('Les limites', P('Une fonction serverless a un temps d’exécution limité et ne garde rien en mémoire entre deux appels. Pour stocker des données, il faut une base ou un service de stockage à côté.'))],
'base-de-donnees': [('Exemple de tableau', '<table class="mini-t"><tr><th>joueur</th><th>revenu</th><th>statut</th></tr><tr><td>Alex</td><td>1 200</td><td>seul</td></tr><tr><td>Sam</td><td>900</td><td>couple</td></tr></table>' + P('Une base relationnelle range les données comme ça : des lignes et des colonnes, un peu comme un tableur. Les noms sont inventés.')),
                    ('Les sauvegardes', P('Une base de données sans sauvegarde, c’est une catastrophe qui attend son heure. On fait des copies régulières, rangées ailleurs, et on vérifie qu’on sait les restaurer.'))],
'responsive': [('Mobile d’abord', P('Aujourd’hui, la majorité des visites se font sur téléphone. Beaucoup de développeurs conçoivent donc d’abord la version mobile, puis l’agrandissent pour l’ordinateur. On appelle ça le « mobile first ».')),
               ('Comment tester', UL('Les outils du navigateur (F12, puis le mode appareil).', 'De vrais téléphones, si possible plusieurs.', 'L’écran en portrait et en paysage.', 'Les gros zooms, pour les personnes qui agrandissent le texte.'))],
'motion-design': [('Les principes', UL('<b>La courbe</b> : rien ne bouge à vitesse constante, tout accélère et ralentit.', '<b>Le décalage</b> : les éléments arrivent les uns après les autres.', '<b>La durée</b> : assez long pour être vu, assez court pour ne pas faire attendre.', '<b>La cohérence</b> : les mêmes mouvements partout.')),
                  ('Sur ce site', P('Le texte qui s’allume au scroll, les cartes qui s’inclinent, les pochettes qui s’écartent, le point du logo qui rebondit. Tout est fait en CSS et JavaScript, sans bibliothèque d’animation.'))],
'cookie': [('Les types de cookies', UL('<b>Indispensables</b> : pour se connecter, garder un panier. Pas besoin d’accord.', '<b>Mesure d’audience</b> : compter les visites. Souvent soumis à accord.', '<b>Publicité</b> : suivre les visiteurs de site en site. Toujours soumis à accord.')),
           ('Le bandeau', P('Un bon bandeau de cookies propose « Accepter » et « Refuser » avec la même facilité, et explique clairement à quoi servent les cookies. Refuser doit être aussi simple qu’accepter.'))],
'rgpd': [('Tes droits', UL('Savoir quelles données sont collectées.', 'Y accéder et les faire corriger.', 'Demander leur suppression.', 'Retirer ton accord à tout moment.', 'Te plaindre auprès de la CNIL.')),
         ('Les sanctions', P('Les entreprises qui ne respectent pas le RGPD peuvent recevoir de très lourdes amendes. En France, c’est la CNIL qui contrôle et sanctionne.'))],
'localstorage': [('Exemple', SN('localStorage.setItem("sx-fun", "1");\nlocalStorage.getItem("sx-fun"); // "1"\nlocalStorage.removeItem("sx-fun");')),
                 ('Ce qu’on n’y met jamais', P('Des mots de passe, des jetons secrets ou des informations sensibles. N’importe quel script de la page peut lire le localStorage. On y range des réglages, pas des secrets.'))],
'iframe': [('Exemple', SN('&lt;iframe src="https://exemple.com/lecteur"\n        title="Lecteur" loading="lazy"&gt;&lt;/iframe&gt;')),
           ('Le chargement après accord', P('Sur les sites de Wyatt, l’iframe n’existe pas au départ. Elle est ajoutée par le JavaScript seulement après ton clic sur « OK ». Avant, aucune connexion n’est faite vers le site intégré.'))],
'cdn': [('Les avantages', UL('Des pages plus rapides, partout dans le monde.', 'Moins de charge sur le serveur principal.', 'Une meilleure résistance aux pics de visites et à certaines attaques.')),
        ('Le revers', P('Le CDN garde des copies. Quand on met à jour un fichier, il faut parfois attendre ou « purger » le cache pour que tout le monde voie la nouvelle version.'))],
'noindex': [('noindex n’est pas un cadenas', P('La balise demande poliment aux moteurs de recherche de ne pas afficher la page. Elle n’empêche personne de la consulter s’il a le lien. Pour protéger une page vraiment privée, il faut un mot de passe.')),
            ('Le cousin robots.txt', P('Le fichier <code>robots.txt</code> dit aux robots quelles pages ne pas explorer. Mais attention : une page bloquée dans robots.txt ne peut pas lire son <code>noindex</code>. Les deux ne se combinent pas toujours comme on croit.'))],
'dom': [('Exemple', SN('const titre = document.querySelector("h1");\ntitre.textContent = "Salut, moi c’est Wyatt.";\ntitre.classList.add("fun");')),
        ('La performance', P('Modifier le DOM coûte un peu de travail au navigateur. Trop de modifications à chaque image, et la page saccade. Les animations fluides utilisent surtout <code>transform</code> et <code>opacity</code>, que le navigateur sait animer très vite.'))],
'cli': [('Les commandes de base', SN('ls        # lister les fichiers\ncd dossier # entrer dans un dossier\nmkdir test # créer un dossier\nclear     # tout effacer')),
        ('Le danger', P('Le terminal fait exactement ce qu’on lui dit, sans demander « tu es sûr ? ». Certaines commandes suppriment des fichiers pour de bon. On ne copie jamais une commande trouvée en ligne sans la comprendre.'))],
'open-source': [('Comment contribuer', UL('Signaler un bug, clairement.', 'Améliorer la documentation.', 'Proposer une correction avec une « pull request ».', 'Remercier les mainteneurs. Ça compte.')),
                ('Les grandes familles de licences', P('Certaines licences, dites permissives (MIT, par exemple), autorisent presque tout. D’autres, comme la GPL, demandent de partager à son tour les modifications. On lit toujours la licence avant de réutiliser un code.'))],
'variable': [('Les types de valeurs', UL('Les nombres : <code>15</code>, <code>3.14</code>.', 'Les textes : <code>"Wyatt"</code>.', 'Les booléens : <code>true</code> ou <code>false</code>.', 'Les listes et les objets.', 'Le vide : <code>null</code> et <code>undefined</code>.')),
             ('let ou const', P('En JavaScript, <code>const</code> crée une valeur qu’on ne réaffecte pas, <code>let</code> une valeur qui peut changer. Bonne habitude : <code>const</code> par défaut, <code>let</code> quand c’est nécessaire.'))],
'boucle': [('Les différentes boucles', UL('<code>for</code> : un nombre de tours connu.', '<code>while</code> : tant qu’une condition est vraie.', '<code>for…of</code> : pour chaque élément d’une liste.') + P('Les trois font tourner, mais chacune est plus lisible dans son cas.')),
           ('La tortue', P('Pour dessiner un carré avec la tortue de Python, on répète quatre fois « avance, tourne de 90 degrés ». Une boucle de quatre tours. C’est souvent la première boucle qu’on écrit de sa vie.'))],
'fonction': [('Les bonnes pratiques', UL('Une fonction fait une seule chose.', 'Son nom dit ce qu’elle fait : <code>calculerImpot</code>, pas <code>truc</code>.', 'Elle reste courte : si elle déborde de l’écran, on la découpe.')),
             ('Dans le bot des impôts', P('Le calcul de l’impôt est une fonction : elle reçoit le profil d’un joueur et la configuration, et renvoie le montant. Partout où le bot a besoin du montant, il appelle la même fonction.'))],
'algorithme': [('Exemple : le tri', P('Trier une main de cartes, c’est un algorithme : on prend une carte, on la glisse à sa place parmi celles déjà triées, et on recommence. Les informaticiens l’appellent le « tri par insertion ».')),
               ('Efficace ou pas', P('Deux algorithmes peuvent donner le même résultat, l’un en une seconde, l’autre en une heure. Une grande partie de l’informatique consiste à trouver les plus rapides. C’est une matière à part entière en NSI.'))],
'ia': [('Comment ça apprend', P('On montre au programme des millions d’exemples. Il ajuste petit à petit ses réglages internes pour faire de moins en moins d’erreurs. Il ne « comprend » pas comme un humain : il repère des régularités.')),
       ('Les bons réflexes', UL('Vérifier les informations importantes.', 'Ne pas partager de données personnelles ou secrètes.', 'Citer quand un texte a été aidé par une IA, si c’est demandé.', 'Garder son esprit critique.'))],
'oauth': [('Les étapes', UL('Le site te redirige vers Discord.', 'Tu acceptes de partager certaines informations.', 'Discord renvoie un code au site.', 'Le site échange ce code contre un jeton d’accès.') + P('Le jeton permet au site de lire seulement ce que tu as accepté de partager.')),
          ('Les « scopes »', P('Les « scopes » définissent ce que le site a le droit de voir : ton pseudo, ton adresse e-mail, tes serveurs… Un site sérieux demande le minimum nécessaire. Toujours lire avant de cliquer sur « Autoriser ».'))],
'regex': [('Les symboles courants', UL('<code>.</code> : n’importe quel caractère.', '<code>*</code> : zéro ou plusieurs fois.', '<code>+</code> : une ou plusieurs fois.', '<code>^</code> et <code>$</code> : début et fin.', '<code>\\d</code> : un chiffre.')),
          ('Où on s’en sert', P('Vérifier qu’une adresse e-mail a l’air correcte, chercher et remplacer dans des milliers de fichiers, découper du texte. Le générateur de Wyattpédia utilise des regex pour placer les liens entre articles.'))],
'erreur-404': [('Les codes à connaître', UL('<b>200</b> : tout va bien.', '<b>301</b> : la page a déménagé.', '<b>403</b> : accès interdit.', '<b>404</b> : introuvable.', '<b>500</b> : le serveur a un problème.')),
               ('Une bonne page 404', P('Une bonne page 404 explique simplement ce qui se passe, propose de revenir à l’accueil, et si possible fait sourire. Celle de siroxtag.fr coche les trois cases.'))],
'debug': [('La console', P('Dans le navigateur, la touche F12 ouvre les outils de développement. La console affiche les erreurs en rouge, avec le fichier et la ligne. C’est souvent le premier endroit où regarder quand une page ne marche plus.')),
          ('La méthode', UL('Reproduire le bug à coup sûr.', 'Réduire le problème au plus petit cas possible.', 'Changer une seule chose à la fois.', 'Noter ce qui a marché, pour la prochaine fois.'))],
'commit': [('Un bon message', SN('Ajoute la recherche dans Wyattpédia\n\nLa recherche filtre les articles par titre,\nalias et résumé, sans recharger la page.') + P('Une première ligne courte qui dit ce que fait le commit, puis, si besoin, une explication.')),
           ('Des petits commits', P('Mieux vaut plusieurs petits commits qu’un énorme. Si un problème arrive, on retrouve plus facilement le changement fautif, et on peut l’annuler sans tout perdre.'))],
'xss': [('Exemple', P('Un site affiche les commentaires des visiteurs sans les filtrer. Un pirate écrit un commentaire qui contient du code. Tous ceux qui lisent la page exécutent ce code sans le savoir.')),
        ('Les trois familles', UL('<b>Stockée</b> : le code est enregistré sur le site, et touche tous les visiteurs.', '<b>Reflétée</b> : le code est dans un lien piégé.', '<b>Basée sur le DOM</b> : le JavaScript de la page insère lui-même le code dangereux.'))],
'injection-sql': [('Pourquoi c’est si connu', P('L’injection SQL est l’une des failles les plus anciennes du web, et pourtant on en trouve encore. Elle apparaît dans tous les classements des risques de sécurité les plus courants.')),
                  ('Ce qu’il ne faut pas faire', P('Construire une requête en collant du texte venant d’un formulaire. Ce qu’il faut faire : des requêtes préparées, des droits limités pour la base, et ne jamais afficher les messages d’erreur détaillés aux visiteurs.'))],
'easter-egg': [('Les plus célèbres', UL('Le code Konami dans de nombreux jeux et sites.', 'Le petit dinosaure qui court quand Chrome n’a plus d’Internet.', 'Des salles secrètes cachées dans les jeux vidéo.')),
               ('Comment bien en cacher un', P('Un bon easter egg ne gêne pas ceux qui ne le trouvent pas, et récompense ceux qui le trouvent. Il doit être drôle, inoffensif, et donner envie d’en chercher d’autres.'))],
# ---------- jargon ----------
'canard-en-caoutchouc': [('Comment faire', UL('Poser le canard face à soi.', 'Lui expliquer ce que le code est censé faire.', 'Lire chaque ligne à voix haute, en expliquant pourquoi elle est là.', 'Remarquer le moment où l’explication ne colle plus.')),
                         ('Les variantes', P('Une plante, une figurine, un ami patient, ou une IA. Le principe reste le même : formuler le problème clairement, c’est déjà le résoudre à moitié.'))],
'code-spaghetti': [('Les autres pâtes', UL('<b>Code lasagne</b> : trop de couches les unes sur les autres.', '<b>Code ravioli</b> : des milliers de petits morceaux impossibles à relier.') + P('Oui, les développeurs aiment la cuisine italienne.')),
                   ('Comment l’éviter', P('Réfléchir un peu avant de coder, découper en fonctions, relire son code le lendemain. Et accepter de réécrire un morceau quand on sent que ça s’emmêle.'))],
'heisenbug': [('Les cousins', UL('<b>Bohrbug</b> : un bug solide, qui se reproduit à chaque fois.', '<b>Mandelbug</b> : un bug si complexe qu’il semble chaotique.', '<b>Schrödinbug</b> : un bug qui n’apparaît qu’au moment où l’on réalise que le code n’aurait jamais dû marcher.') + P('Tous des noms de physiciens et mathématiciens. Les développeurs ont une passion pour les sciences.')),
              ('Comment l’attraper', P('Enregistrer un maximum d’informations sans ralentir le programme, et chercher ce qui dépend du temps : animations, chargements, requêtes réseau.'))],
'ca-marche-sur-ma-machine': [('Les vraies causes', UL('Un fichier en cache sur l’ordinateur du développeur.', 'Une version différente du navigateur ou de Node.js.', 'Un réglage oublié, ou une variable secrète présente seulement en local.', 'Un écran plus grand qui cache un problème de mise en page.')),
                             ('La solution moderne', P('Les conteneurs, comme Docker, servent justement à emballer un programme avec tout son environnement. Résultat : il tourne pareil partout. La phrase devient « ça marche dans le conteneur ».'))],
'off-by-one': [('Exemple', SN('const liste = ["a", "b", "c"];\nfor (let i = 0; i &lt;= liste.length; i++) {\n  console.log(liste[i]); // le dernier tour affiche undefined\n}') + P('Le <code>&lt;=</code> aurait dû être un <code>&lt;</code>. Une seule lettre de différence.')),
               ('Le problème des poteaux', P('Pour une clôture de 10 mètres avec un poteau tous les mètres, il faut 11 poteaux, pas 10. C’est le « problème des poteaux de clôture », l’ancêtre de toutes les erreurs de un.'))],
'tabs-vs-espaces': [('Le combien', P('Même chez ceux qui utilisent des espaces, le débat continue : deux espaces ou quatre ? Python recommande quatre, beaucoup de projets JavaScript en utilisent deux.')),
                    ('L’avis de Wyattpédia', P('Peu importe, tant que tout le projet fait pareil. Un fichier qui mélange les deux est le vrai problème. Et en Python, ce mélange peut même empêcher le programme de tourner.'))],
'yak-shaving': [('L’origine', P('L’expression vient d’un dessin animé américain des années 1990, où un personnage enchaînait des tâches absurdes, dont tondre un yak. Elle a été reprise par les développeurs pour décrire ce piège très courant.')),
                ('Quand c’est utile', P('Parfois, tondre le yak est nécessaire : sans cet outil réparé, on ne peut vraiment pas avancer. Tout l’art est de savoir faire la différence entre un yak indispensable et un yak de procrastination.'))],
'nan': [('D’où ça vient', P('NaN vient de la norme IEEE 754, qui décrit comment les ordinateurs représentent les nombres à virgule. Cette norme est utilisée par presque tous les langages, pas seulement JavaScript.')),
        ('Le piège classique', P('Un texte transformé en nombre alors qu’il contient des lettres donne NaN. Et NaN « contamine » tout : NaN + 1 donne NaN. Un seul champ mal rempli, et tout le calcul devient NaN.'))],
'undefined': [('Exemple', SN('let a;\nconsole.log(a);    // undefined\nlet b = null;\nconsole.log(b);    // null\nnull == undefined  // true\nnull === undefined // false')),
              ('Le conseil', P('Utiliser <code>===</code> plutôt que <code>==</code> pour comparer. Le double égal fait des conversions surprenantes, le triple égal compare exactement.'))],
'race-condition': [('Dans la vraie vie', P('Deux personnes achètent en même temps le dernier billet d’un concert. Si le site vérifie le stock, puis vend, sans bloquer entre les deux, il peut vendre deux fois le même billet.')),
                   ('La parade', P('On rend l’opération « atomique » : la vérification et la vente se font d’un seul bloc, que rien ne peut interrompre. Les bases de données proposent des outils pour ça, appelés transactions.'))],
'conflit-de-fusion': [('À quoi ça ressemble', SN('&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD\nconst titre = "Wyatt LE";\n=======\nconst titre = "Wyatt LE.";\n&gt;&gt;&gt;&gt;&gt;&gt;&gt; autre-branche') + P('Git montre les deux versions. À l’humain de choisir. Ici, la version avec le point gagne, évidemment.')),
                      ('Comment les éviter', UL('Récupérer les derniers changements avant de commencer.', 'Faire des petits commits souvent.', 'Ne pas modifier le même fichier à deux endroits en même temps.'))],
'vendredi-prod': [('Les autres règles non écrites', UL('Ne jamais tester directement en production.', 'Toujours avoir une sauvegarde avant une grosse modification.', 'Ne pas lancer une migration de base de données juste avant de partir.')),
                  ('Le gel', P('Certaines entreprises décrètent un « gel » des mises en ligne avant les fêtes ou les grands événements. Pas de changement, pas de risque. Une sagesse que l’on comprend vraiment après son premier incident.'))],
'hello-world': [('Dans plusieurs langages', SN('print("Hello, World!")              # Python\nconsole.log("Hello, World!");        // JavaScript\necho "Hello, World!";                // PHP')),
                ('Pourquoi c’est important', P('Ce programme minuscule vérifie que tout est bien installé : l’éditeur, le langage, le terminal. Si « Hello, World! » s’affiche, on peut commencer à construire. Si ça ne marche pas, au moins, le problème est petit.'))],
'boucle-infinie': [('Comment en sortir', UL('Dans un terminal : <code>Ctrl + C</code>.', 'Dans un navigateur : fermer l’onglet, ou attendre le message « la page ne répond pas ».', 'Dans la vraie vie : aller dormir.')),
                   ('La boucle des jeux vidéo', P('Un jeu vidéo est une boucle infinie volontaire : lire les touches, mettre à jour le monde, dessiner l’image, recommencer. Des dizaines de fois par seconde, jusqu’à ce qu’on quitte le jeu.'))],
'bug-an-2000': [('Le prochain', P('Un problème du même genre est annoncé pour 2038 sur certains systèmes, qui comptent le temps en secondes depuis 1970 sur un nombre trop petit. Le travail pour l’éviter est déjà en cours.')),
                ('Ce que ça a coûté', P('Les corrections ont mobilisé des équipes dans le monde entier pendant des années. On estime que des centaines de milliards de dollars y ont été consacrés au total. Le prix d’un raccourci.'))],
'konami-code': [('Pourquoi il est si célèbre', P('Le code rendait certains jeux beaucoup plus faciles, et s’est transmis de joueur en joueur, à l’époque où Internet n’existait pas encore pour tout le monde. Il est devenu un symbole de la culture du jeu vidéo.')),
                ('Comment il marche ici', P('Le terminal écoute les touches du clavier. Si la séquence complète est tapée dans l’ordre, le mode fun s’active, l’écran tremble et un message apparaît. Dix touches, une ligne de JavaScript par touche ou presque.'))],
'mode-sombre': [('Comment on le fait en CSS', SN('@media (prefers-color-scheme: dark) {\n  body { background: #111; color: #eee; }\n}') + P('Le site peut suivre automatiquement le réglage de ton appareil.')),
                ('Les pièges', P('Un mode sombre ne consiste pas à tout inverser. Le noir pur fatigue les yeux à côté du blanc pur, les couleurs doivent être adoucies, et les images parfois assombries. C’est un vrai travail de design.'))],
}
